class Solution {
public:
    void setZeroes(vector<vector<int>>& matrix) {
        int n = matrix.size();
                int m = matrix[0].size();
                        bool setRows = false;
                                bool setCols = false;

                                        for(int i=0;i<n;i++) {
                                                    if(matrix[i][0] == 0) {
                                                                    setRows = true;
                                                                                }
                                                                                        }
                                                                                                for(int j=0;j<m;j++) {
                                                                                                            if(matrix[0][j] == 0) {
                                                                                                                            setCols = true;
                                                                                                                                        }
                                                                                                                                                }

                                                                                                                                                        for(int i=1;i<n;i++) {
                                                                                                                                                                    for(int j=1;j<m;j++) {
                                                                                                                                                                                    if(matrix[i][j] == 0) {
                                                                                                                                                                                                        matrix[0][j] = 0;
                                                                                                                                                                                                                            matrix[i][0] = 0;
                                                                                                                                                                                                                                            }
                                                                                                                                                                                                                                                        }
                                                                                                                                                                                                                                                                }
                                                                                                                                                                                                                                                                        // traverse from here on
                                                                                                                                                                                                                                                                                for(int i=1;i<n;i++) {
                                                                                                                                                                                                                                                                                            if(matrix[i][0] == 0) {
                                                                                                                                                                                                                                                                                                            for(int j=1;j<m;j++) {
                                                                                                                                                                                                                                                                                                                                matrix[i][j] = 0;
                                                                                                                                                                                                                                                                                                                                                }
                                                                                                                                                                                                                                                                                                                                                            }
                                                                                                                                                                                                                                                                                                                                                                    }
                                                                                                                                                                                                                                                                                                                                                                            for(int j=1;j<m;j++) {
                                                                                                                                                                                                                                                                                                                                                                                        if(matrix[0][j] == 0) {
                                                                                                                                                                                                                                                                                                                                                                                                        for(int i=1;i<n;i++) {
                                                                                                                                                                                                                                                                                                                                                                                                                            matrix[i][j] = 0;
                                                                                                                                                                                                                                                                                                                                                                                                                                            }
                                                                                                                                                                                                                                                                                                                                                                                                                                                        }
                                                                                                                                                                                                                                                                                                                                                                                                                                                                }
                                                                                                                                                                                                                                                                                                                                                                                                                                                                        if(setRows) {
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                    for(int i=0;i<n;i++) {
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                    matrix[i][0] = 0;
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                }
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                        }
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                if(setCols) {
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                            for(int j=0;j<m;j++) {
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                            matrix[0][j] = 0;
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                        }
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                }
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                        return;
    }
};
